//! Reduction functions: aggregate a tensor into a scalar or along axes.
//!
//! Families (`sum`, `prod`, `mean`, `var`, `std`, `min`, `max`, `argmin`,
//! `argmax`, `nanargmin`, `nanargmax`, `count_nonzero`, `all`, `any`,
//! `l2_norm`) are generated by the local `trait_reduction!` macro, and
//! [`allclose`] is hand-written. Each family exposes:
//!
//! - `<fam>(tensor)`: reduce **all** elements to a scalar;
//! - `<fam>_all(tensor)`: the same, explicit form;
//! - `<fam>_axes(tensor, axes)`: reduce along the given axes (negative values count from the back;
//!   `None` reduces everything into a 0-D tensor);
//! - fallible `_f` versions of all of the above.
//!
//! The arg* families (`argmin`, `argmax`, and their `unraveled_` variants from
//! the `trait_reduction_arg!` macro) return element indices instead of values:
//! the all-element forms return the flat (linear) index, and the `_axes`
//! forms return index tensors.
//!
//! <div class="warning">
//!
//! **Row/Column Major Notice**
//!
//! This function behaves differently on default orders ([`RowMajor`] and [`ColMajor`]) of device.
//!
//! </div>
//!
//! The note above applies to the arg* families and `_axes` result layouts
//! only: value aggregations (`sum`, `mean`, `max`, ...) produce the same
//! values under both orders, and `_axes` outputs keep the input's axis
//! arrangement ([`TensorIterOrder::K`]) regardless of the device default
//! order. The arg* functions are order-independent: ties resolve to the first
//! occurrence in row-major order, and the all-element forms return a
//! row-major flat index even on a [`ColMajor`] device. The
//! `nanargmin`/`nanargmax` families follow NumPy's `nanarg*`: NaN elements
//! are skipped wherever they appear, and an all-NaN input raises
//! `InvalidValue` ("All-NaN slice encountered"); use these for inputs that
//! may contain NaN. See [`order_semantics`](crate::order_semantics).
//!
//! # Examples
//!
//! ```rust
//! # use rstsr::prelude::*;
//! # let mut device = DeviceCpu::default();
//! # device.set_default_order(RowMajor);
//! let a = rt::tensor_from_nested!([[1, 2, 3], [4, 5, 6]], &device);
//!
//! // reduce everything to a scalar
//! println!("{}", rt::sum(&a));
//! // 21
//! println!("{}", rt::sum_axes(&a, 0));
//! // [ 5 7 9]
//! println!("{}", rt::count_nonzero_axes(&a, 0));
//! // [ 2 2 2]
//! # assert_eq!(rt::sum(&a), 21);
//! # assert_eq!(format!("{}", rt::sum_axes(&a, 0)), "[ 5 7 9]");
//! ```
//!
//! The arg* families return indices:
//!
//! ```rust
//! # use rstsr::prelude::*;
//! # let mut device = DeviceCpu::default();
//! # device.set_default_order(RowMajor);
//! let a = rt::tensor_from_nested!([[1.0, 5.0, 3.0], [4.0, 5.0, 2.0]], &device);
//! println!("{}", rt::argmax(&a));
//! // 1
//! println!("{}", rt::argmax_axes(&a, 0));
//! // [ 1 0 0]
//! # assert_eq!(rt::argmax(&a), 1);
//! # assert_eq!(format!("{}", rt::argmax_axes(&a, 0)), "[ 1 0 0]");
//! ```

use crate::prelude_dev::*;

/* #region reduction args */

/// Arguments of reduction operations: axes and keepdims.
///
/// All fields are optional; `None` means the field's default behavior:
/// [`axes`](ReduceArgs::axes) reduces all elements, and
/// [`keepdims`](ReduceArgs::keepdims) drops the reduced axes.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ReduceArgs {
    /// Axes to reduce; negative values count from the back.
    /// `None` (default) reduces all elements like [`AxesIndex::None`].
    pub axes: Option<AxesIndex<isize>>,

    /// Whether to keep the reduced axes as size-1 dimensions. Default `false`.
    pub keepdims: Option<bool>,
}

impl ReduceArgs {
    /// Set the axes to reduce, builder-style.
    pub fn axes(mut self, axes: impl Into<AxesIndex<isize>>) -> Self {
        self.axes = Some(axes.into());
        self
    }

    /// Set whether the reduced axes are kept, builder-style.
    pub fn keepdims(mut self, keepdims: bool) -> Self {
        self.keepdims = Some(keepdims);
        self
    }

    pub(crate) fn resolve(&self) -> (AxesIndex<isize>, bool) {
        (self.axes.clone().unwrap_or(AxesIndex::None), self.keepdims.unwrap_or(false))
    }
}

/// Arguments of `var`/`std` operations: axes, keepdims, and correction.
///
/// Same conversion overloads as [`ReduceArgs`]; the `correction` (Delta
/// degrees of freedom) is set through the struct literal or
/// [`VarArgs::correction`].
#[derive(Debug, Clone, PartialEq, Default)]
pub struct VarArgs {
    /// Axes to reduce; negative values count from the back.
    /// `None` (default) reduces all elements like [`AxesIndex::None`].
    pub axes: Option<AxesIndex<isize>>,

    /// Whether to keep the reduced axes as size-1 dimensions. Default `false`.
    pub keepdims: Option<bool>,

    /// Delta degrees of freedom (Array-API `correction`); the divisor is
    /// `M - correction` where `M` is the number of reduced elements.
    /// Default `0.0`; the result is NaN when `M - correction <= 0`.
    pub correction: Option<f64>,
}

impl VarArgs {
    /// Set the axes to reduce, builder-style.
    pub fn axes(mut self, axes: impl Into<AxesIndex<isize>>) -> Self {
        self.axes = Some(axes.into());
        self
    }

    /// Set whether the reduced axes are kept, builder-style.
    pub fn keepdims(mut self, keepdims: bool) -> Self {
        self.keepdims = Some(keepdims);
        self
    }

    /// Set the Delta degrees of freedom (`correction`), builder-style.
    pub fn correction(mut self, correction: f64) -> Self {
        self.correction = Some(correction);
        self
    }

    pub(crate) fn resolve(&self) -> (AxesIndex<isize>, bool, f64) {
        (self.axes.clone().unwrap_or(AxesIndex::None), self.keepdims.unwrap_or(false), self.correction.unwrap_or(0.0))
    }
}

macro_rules! impl_reduce_args_axes_conversions {
    ($Args:ident; $($T:ty),* $(,)?) => {$(
        impl TryFrom<$T> for $Args {
            type Error = Error;

            fn try_from(value: $T) -> Result<Self> {
                let axes: AxesIndex<isize> = value.try_into()?;
                Ok(Self { axes: Some(axes), ..Default::default() })
            }
        }

        impl<const N: usize> TryFrom<[$T; N]> for $Args {
            type Error = Error;

            fn try_from(value: [$T; N]) -> Result<Self> {
                let axes: AxesIndex<isize> = value.try_into()?;
                Ok(Self { axes: Some(axes), ..Default::default() })
            }
        }

        impl TryFrom<Vec<$T>> for $Args {
            type Error = Error;

            fn try_from(value: Vec<$T>) -> Result<Self> {
                let axes: AxesIndex<isize> = value.try_into()?;
                Ok(Self { axes: Some(axes), ..Default::default() })
            }
        }

        impl TryFrom<&[$T]> for $Args {
            type Error = Error;

            fn try_from(value: &[$T]) -> Result<Self> {
                let axes: AxesIndex<isize> = value.try_into()?;
                Ok(Self { axes: Some(axes), ..Default::default() })
            }
        }

        #[allow(clippy::needless_update)]
        impl TryFrom<($T, bool)> for $Args {
            type Error = Error;

            fn try_from(value: ($T, bool)) -> Result<Self> {
                let axes: AxesIndex<isize> = value.0.try_into()?;
                Ok(Self { axes: Some(axes), keepdims: Some(value.1), ..Default::default() })
            }
        }

        #[allow(clippy::needless_update)]
        impl<const N: usize> TryFrom<([$T; N], bool)> for $Args {
            type Error = Error;

            fn try_from(value: ([$T; N], bool)) -> Result<Self> {
                let axes: AxesIndex<isize> = value.0.try_into()?;
                Ok(Self { axes: Some(axes), keepdims: Some(value.1), ..Default::default() })
            }
        }

        #[allow(clippy::needless_update)]
        impl TryFrom<(Vec<$T>, bool)> for $Args {
            type Error = Error;

            fn try_from(value: (Vec<$T>, bool)) -> Result<Self> {
                let axes: AxesIndex<isize> = value.0.try_into()?;
                Ok(Self { axes: Some(axes), keepdims: Some(value.1), ..Default::default() })
            }
        }
    )*};
}

macro_rules! impl_reduce_args_conversions {
    ($Args:ident) => {
        impl TryFrom<()> for $Args {
            type Error = Error;

            fn try_from(_: ()) -> Result<Self> {
                Ok(Self::default())
            }
        }

        impl TryFrom<bool> for $Args {
            type Error = Error;

            fn try_from(keepdims: bool) -> Result<Self> {
                Ok(Self { keepdims: Some(keepdims), ..Default::default() })
            }
        }

        impl TryFrom<AxesIndex<isize>> for $Args {
            type Error = Error;

            fn try_from(axes: AxesIndex<isize>) -> Result<Self> {
                Ok(Self { axes: Some(axes), ..Default::default() })
            }
        }

        #[allow(clippy::needless_update)]
        impl TryFrom<(AxesIndex<isize>, bool)> for $Args {
            type Error = Error;

            fn try_from(value: (AxesIndex<isize>, bool)) -> Result<Self> {
                Ok(Self { axes: Some(value.0), keepdims: Some(value.1), ..Default::default() })
            }
        }

        impl_reduce_args_axes_conversions!($Args; isize, i32, usize, u32, i64, u64);
    };
}

impl_reduce_args_conversions!(ReduceArgs);
impl_reduce_args_conversions!(VarArgs);

/// Rebuild a reduced tensor with the reduced axes re-inserted as size-1
/// dimensions (`keepdims` post-processing of `*_with_args`).
pub(crate) fn reduction_keepdims<S>(
    tensor: TensorBase<S, IxD>,
    axes: AxesIndex<isize>,
    input_ndim: usize,
) -> Result<TensorBase<S, IxD>> {
    let axes = match axes {
        AxesIndex::None => (0..input_ndim).map(|x| x as isize).collect(),
        axes => normalize_axes_index(axes, input_ndim, false, true)?,
    };
    into_expand_dims_f(tensor, axes)
}

/* #endregion */

macro_rules! trait_reduction {
    ($OpReduceAPI: ident, $fn: ident, $fn_f: ident, $fn_axes: ident, $fn_axes_f: ident, $fn_all: ident, $fn_all_f: ident) => {
        pub fn $fn_all_f<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> Result<B::TOut>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            let tensor = tensor.view();
            tensor.device().$fn_all(tensor.raw(), tensor.layout())
        }

        pub fn $fn_axes_f<T, B, D>(
            tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>,
            axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
        ) -> Result<Tensor<B::TOut, B, IxD>>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D> + DeviceCreationAnyAPI<B::TOut>,
        {
            let axes = axes.try_into().map_err(Into::into)?;
            let tensor = tensor.view();

            match axes {
                AxesIndex::None => {
                    let sum = tensor.device().$fn_all(tensor.raw(), tensor.layout())?;
                    let storage = tensor.device().outof_cpu_vec(vec![sum])?;
                    let layout = Layout::new(vec![], vec![], 0)?;
                    Tensor::new_f(storage, layout)
                },
                _ => {
                    let (storage, layout) = tensor.device().$fn_axes(tensor.raw(), tensor.layout(), axes.as_ref())?;
                    Tensor::new_f(storage, layout)
                },
            }
        }

        pub fn $fn_all<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> B::TOut
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all_f(tensor).rstsr_unwrap()
        }

        pub fn $fn_axes<T, B, D>(
            tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>,
            axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
        ) -> Tensor<B::TOut, B, IxD>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D> + DeviceCreationAnyAPI<B::TOut>,
        {
            $fn_axes_f(tensor, axes).rstsr_unwrap()
        }

        pub fn $fn_f<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> Result<B::TOut>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all_f(tensor)
        }

        pub fn $fn<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> B::TOut
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all(tensor)
        }

        impl<R, T, B, D> TensorAny<R, T, B, D>
        where
            R: DataAPI<Data = <B as DeviceRawAPI<T>>::Raw>,
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            pub fn $fn_all_f(&self) -> Result<B::TOut> {
                $fn_all_f(self)
            }

            pub fn $fn_all(&self) -> B::TOut {
                $fn_all(self)
            }

            pub fn $fn_axes_f(
                &self,
                axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
            ) -> Result<Tensor<B::TOut, B, IxD>>
            where
                B: DeviceCreationAnyAPI<B::TOut>,
            {
                $fn_axes_f(self, axes)
            }

            pub fn $fn_axes(&self, axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>) -> Tensor<B::TOut, B, IxD>
            where
                B: DeviceCreationAnyAPI<B::TOut>,
            {
                $fn_axes(self, axes)
            }

            pub fn $fn_f(&self) -> Result<B::TOut> {
                $fn_f(self)
            }

            pub fn $fn(&self) -> B::TOut {
                $fn(self)
            }
        }
    };
}

