macro_rules! trait_reduction_arg {
    ($OpReduceAPI: ident, $fn: ident, $fn_f: ident, $fn_axes: ident, $fn_axes_f: ident, $fn_all: ident, $fn_all_f: ident) => {
        pub fn $fn_all_f<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> Result<D>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            let tensor = tensor.view();
            tensor.device().$fn_all(tensor.raw(), tensor.layout())
        }

        pub fn $fn_axes_f<T, B, D>(
            tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>,
            axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
        ) -> Result<Tensor<IxD, B, IxD>>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D> + DeviceAPI<IxD> + DeviceCreationAnyAPI<IxD>,
        {
            let axes = axes.try_into().map_err(Into::into)?;
            let tensor = tensor.view();

            match axes {
                AxesIndex::None => {
                    // special case for reducing all axes
                    let arg = tensor.device().$fn_all(tensor.raw(), tensor.layout())?;
                    let storage = tensor.device().outof_cpu_vec(vec![arg.into()])?;
                    let layout = Layout::new(vec![], vec![], 0)?;
                    Tensor::new_f(storage, layout)
                },
                _ => {
                    let (storage, layout) = tensor.device().$fn_axes(tensor.raw(), tensor.layout(), axes.as_ref())?;
                    Tensor::new_f(storage, layout)
                },
            }
        }

        pub fn $fn_all<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> D
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all_f(tensor).rstsr_unwrap()
        }

        pub fn $fn_axes<T, B, D>(
            tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>,
            axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
        ) -> Tensor<IxD, B, IxD>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D> + DeviceAPI<IxD> + DeviceCreationAnyAPI<IxD>,
        {
            $fn_axes_f(tensor, axes).rstsr_unwrap()
        }

        pub fn $fn_f<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> Result<D>
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all_f(tensor)
        }

        pub fn $fn<T, B, D>(tensor: impl TensorViewAPI<Type = T, Backend = B, Dim = D>) -> D
        where
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            $fn_all(tensor)
        }

        impl<R, T, B, D> TensorAny<R, T, B, D>
        where
            R: DataAPI<Data = <B as DeviceRawAPI<T>>::Raw>,
            D: DimAPI,
            B: $OpReduceAPI<T, D>,
        {
            pub fn $fn_all_f(&self) -> Result<D> {
                $fn_all_f(self)
            }

            pub fn $fn_all(&self) -> D {
                $fn_all(self)
            }

            pub fn $fn_axes_f(
                &self,
                axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>,
            ) -> Result<Tensor<IxD, B, IxD>>
            where
                B: DeviceAPI<IxD> + DeviceCreationAnyAPI<IxD>,
            {
                $fn_axes_f(self, axes)
            }

            pub fn $fn_axes(&self, axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>) -> Tensor<IxD, B, IxD>
            where
                B: DeviceAPI<IxD> + DeviceCreationAnyAPI<IxD>,
            {
                $fn_axes(self, axes)
            }

            pub fn $fn_f(&self) -> Result<D> {
                $fn_f(self)
            }

            pub fn $fn(&self) -> D {
                $fn(self)
            }
        }
    };
}

