/* #region allclose */

/// Whether two tensors are element-wise equal within tolerances
/// (`all(|a - b| <= atol + rtol * |b|)`).
///
/// The two tensors are broadcast against each other; the result is a single
/// `bool`. Default tolerances (for `f64`): `rtol = 1.0e-5`, `atol = 1.0e-8`,
/// `equal_nan = false` (see [`IsCloseArgs`]).
///
/// This function behaves identically under [`RowMajor`] and [`ColMajor`] device default orders.
///
/// # Parameters
///
/// - `tensor_a` / `tensor_b`: the tensors to compare (broadcast against each other).
/// - `isclose_args`: tolerances; anything that converts into [`IsCloseArgs`] — pass `None` for the
///   defaults.
///
/// # Returns
///
/// - `bool`: `true` if every element pair is close.
///
/// # Examples
///
/// ```rust
/// # use rstsr::prelude::*;
/// # let mut device = DeviceCpu::default();
/// # device.set_default_order(RowMajor);
/// let a = rt::tensor_from_nested!([[1.0, 5.0, 3.0], [4.0, 5.0, 2.0]], &device);
/// let b = rt::tensor_from_nested!([[1.0, 5.0, 3.0], [4.0, 5.0, 2.0]], &device);
/// println!("{}", rt::allclose(&a, &b, None));
/// // true
/// let c = rt::tensor_from_nested!([[1.0, 5.1, 3.0], [4.0, 5.0, 2.0]], &device);
/// println!("{}", rt::allclose(&a, &c, None));
/// // false
/// # assert!(rt::allclose(&a, &b, None));
/// # assert!(!rt::allclose(&a, &c, None));
/// ```
///
/// # Notes of API accordance
///
/// - NumPy: `numpy.allclose(a, b, rtol=1e-05, atol=1e-08, equal_nan=False)` ([`numpy.allclose`](https://numpy.org/doc/stable/reference/generated/numpy.allclose.html))
/// - RSTSR: `rt::allclose(&a, &b, None)`; tolerances are grouped into [`IsCloseArgs`]. The macro
///   form `allclose!(&a, &b)` is also available.
///
/// # See also
///
/// ## Similar function from other crates/libraries
///
/// - NumPy: [`numpy.allclose`](https://numpy.org/doc/stable/reference/generated/numpy.allclose.html)
///
/// ## Related functions in RSTSR
///
/// - `isclose`: element-wise closeness is available on the dtype traits (`ExtFloat::isclose` of
///   `rstsr-dtype-traits`).
///
/// ## Variants of this function
///
/// - [`allclose_f`]: fallible version.
/// - [`allclose_all`] / [`allclose_all_f`]: explicit all-element form.
/// - Macro: `allclose!(&a, &b)` (crate-level exported, same name as the function).
pub fn allclose_all_f<TA, TB, TE, B, DA, DB>(
    tensor_a: impl TensorViewAPI<Type = TA, Backend = B, Dim = DA>,
    tensor_b: impl TensorViewAPI<Type = TB, Backend = B, Dim = DB>,
    isclose_args: impl Into<IsCloseArgs<TE>>,
) -> Result<bool>
where
    DA: DimAPI,
    DB: DimAPI,
    B: DeviceAPI<bool> + OpAllCloseAPI<TA, TB, TE, IxD>,
    TE: 'static,
{
    let tensor_a = tensor_a.view();
    let tensor_b = tensor_b.view();
    let isclose_args = isclose_args.into();
    let device = tensor_a.device();

    // check device
    rstsr_assert!(tensor_a.device().same_device(tensor_b.device()), DeviceMismatch)?;

    // check and broadcast layout

    let la = tensor_a.layout().to_dim::<IxD>()?;
    let lb = tensor_b.layout().to_dim::<IxD>()?;
    let default_order = device.default_order();
    let (la_b, lb_b) = broadcast_layout(&la, &lb, default_order)?;

    device.allclose_all(tensor_a.raw(), &la_b, tensor_b.raw(), &lb_b, &isclose_args)
}

pub fn allclose_all<TA, TB, TE, B, DA, DB>(
    tensor_a: impl TensorViewAPI<Type = TA, Backend = B, Dim = DA>,
    tensor_b: impl TensorViewAPI<Type = TB, Backend = B, Dim = DB>,
    isclose_args: impl Into<IsCloseArgs<TE>>,
) -> bool
where
    DA: DimAPI,
    DB: DimAPI,
    B: DeviceAPI<bool> + OpAllCloseAPI<TA, TB, TE, IxD>,
    TE: 'static,
{
    allclose_all_f(tensor_a, tensor_b, isclose_args).rstsr_unwrap()
}

pub fn allclose_f<TA, TB, TE, B, DA, DB>(
    tensor_a: impl TensorViewAPI<Type = TA, Backend = B, Dim = DA>,
    tensor_b: impl TensorViewAPI<Type = TB, Backend = B, Dim = DB>,
    isclose_args: impl Into<IsCloseArgs<TE>>,
) -> Result<bool>
where
    DA: DimAPI,
    DB: DimAPI,
    B: DeviceAPI<bool> + OpAllCloseAPI<TA, TB, TE, IxD>,
    TE: 'static,
{
    allclose_all_f(tensor_a, tensor_b, isclose_args)
}

pub fn allclose<TA, TB, TE, B, DA, DB>(
    tensor_a: impl TensorViewAPI<Type = TA, Backend = B, Dim = DA>,
    tensor_b: impl TensorViewAPI<Type = TB, Backend = B, Dim = DB>,
    isclose_args: impl Into<IsCloseArgs<TE>>,
) -> bool
where
    DA: DimAPI,
    DB: DimAPI,
    B: DeviceAPI<bool> + OpAllCloseAPI<TA, TB, TE, IxD>,
    TE: 'static,
{
    allclose_f(tensor_a, tensor_b, isclose_args).rstsr_unwrap()
}

#[macro_export]
macro_rules! allclose {
    ($tensor_a:expr, $tensor_b:expr, $isclose_args:expr) => {{
        use rstsr::prelude::rstsr_funcs::allclose;
        allclose($tensor_a, $tensor_b, $isclose_args)
    }};
    ($tensor_a:expr, $tensor_b:expr) => {{
        use rstsr::prelude::rstsr_funcs::allclose;
        allclose($tensor_a, $tensor_b, None)
    }};
}

